export function lettersToNum(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

export function numToLetters(n) {
  let s = ''
  while (n > 0) {
    n -= 1
    s = String.fromCharCode(65 + (n % 26)) + s
    n = Math.floor(n / 26)
  }
  return s
}

// word must already be upper-cased. Returns { col, row, key } or null.
export function parseAddress(word) {
  const m = /^([A-Z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = lettersToNum(m[1])
  return { col, row, key: m[1] + row }
}
"}

