{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-ZCJO32/src/values.js","content":"// Value model: number, text, bool, error.

export const ERROR_TOKENS = new Set([
  '#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!',
])

export function numVal(v) { return { type: 'number', value: v } }
export function textVal(v) { return { type: 'text', value: v } }
export function boolVal(v) { return { type: 'bool', value: v } }
export function errVal(v) { return { type: 'error', value: v } }

// Parse a literal (non-formula) cell content string.
export function parseLiteral(content) {
  if (content === '') return numVal(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return numVal(parseFloat(content))
  if (ERROR_TOKENS.has(content)) return errVal(content)
  return textVal(content)
}

// Read a value as a number for arithmetic. Returns { ok:true, num } or { ok:false, err }.
export function readNumber(v) {
  if (v.type === 'number') return { ok: true, num: v.value }
  if (v.type === 'bool') return { ok: true, num: v.value ? 1 : 0 }
  if (v.type === 'error') return { ok: false, err: v.value }
  return { ok: false, err: '#VALUE!' } // text
}

function typeRank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  if (v.type === 'bool') return 2
  return 3
}

// Compare two non-error values. Returns -1, 0, or 1.
export function compareValues(a, b) {
  const ra = typeRank(a)
  const rb = typeRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.type === 'number' || a.type === 'text') {
    return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  }
  if (a.type === 'bool') {
    const av = a.value ? 1 : 0
    const bv = b.value ? 1 : 0
    return av < bv ? -1 : av > bv ? 1 : 0
  }
  return 0
}

// Format a value for `values` output.
export function formatValue(v) {
  if (v.type === 'number') return formatNumber(v.value)
  if (v.type === 'error') return v.value
  if (v.type === 'bool') return v.value ? 'TRUE' : 'FALSE'
  return v.value
}

export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}
"}

