{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-ZCJO32/src/parser.js","content":"// Tokenizer and recursive-descent parser for formula bodies.
//
// AST node shapes:
//   { type: 'num', value }
//   { type: 'bool', value }
//   { type: 'addr', word }              -- word is upper-cased
//   { type: 'range', from, to }         -- from/to are upper-cased words
//   { type: 'unary', op, operand }
//   { type: 'bin', op, left, right }
//   { type: 'cmp', op, left, right }
//   { type: 'call', name, args }        -- name is upper-cased, args is a list of nodes

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function tokenize(s) {
  const tokens = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i += 1; continue }
    if (c >= '0' && c <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i))
      tokens.push({ type: 'NUM', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(s.slice(i))
      tokens.push({ type: 'WORD', value: m[0].toUpperCase() })
      i += m[0].length
      continue
    }
    if (c === '(') { tokens.push({ type: 'LP' }); i += 1; continue }
    if (c === ')') { tokens.push({ type: 'RP' }); i += 1; continue }
    if (c === ',') { tokens.push({ type: 'COMMA' }); i += 1; continue }
    if (c === ':') { tokens.push({ type: 'COLON' }); i += 1; continue }
    const two = s.slice(i, i + 2)
    if (two === '<=' || two === '>=' || two === '<>') {
      tokens.push({ type: 'OP', value: two })
      i += 2
      continue
    }
    if ('^*/+-=<>'.includes(c)) {
      tokens.push({ type: 'OP', value: c })
      i += 1
      continue
    }
    return null // unrecognized character
  }
  return tokens
}

// Returns an AST node, or null on grammar failure.
export function parseFormula(body) {
  const tokens = tokenize(body)
  if (tokens === null) return null
  let pos = 0

  const peek = () => tokens[pos]
  const atEnd = () => pos >= tokens.length
  const next = () => tokens[pos++]

  function parseExpr() {
    return parseComparison()
  }

  function parseComparison() {
    let left = parseAdditive()
    if (left === null) return null
    while (!atEnd() && peek().type === 'OP' && COMPARE_OPS.has(peek().value)) {
      const op = next().value
      const right = parseAdditive()
      if (right === null) return null
      left = { type: 'cmp', op, left, right }
    }
    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    if (left === null) return null
    while (!atEnd() && peek().type === 'OP' && (peek().value === '+' || peek().value === '-')) {
      const op = next().value
      const right = parseMultiplicative()
      if (right === null) return null
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  function parseMultiplicative() {
    let left = parsePower()
    if (left === null) return null
    while (!atEnd() && peek().type === 'OP' && (peek().value === '*' || peek().value === '/')) {
      const op = next().value
      const right = parsePower()
      if (right === null) return null
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  function parsePower() {
    const left = parseUnary()
    if (left === null) return null
    if (!atEnd() && peek().type === 'OP' && peek().value === '^') {
      next()
      const right = parsePower() // right-associative
      if (right === null) return null
      return { type: 'bin', op: '^', left, right }
    }
    return left
  }

  function parseUnary() {
    if (!atEnd() && peek().type === 'OP' && (peek().value === '+' || peek().value === '-')) {
      const op = next().value
      const operand = parseUnary()
      if (operand === null) return null
      return { type: 'unary', op, operand }
    }
    return parsePrimary()
  }

  function parseArgList() {
    const args = []
    if (!atEnd() && peek().type === 'RP') return args
    while (true) {
      const arg = parseExpr()
      if (arg === null) return null
      args.push(arg)
      if (!atEnd() && peek().type === 'COMMA') { next(); continue }
      break
    }
    return args
  }

  function parsePrimary() {
    if (atEnd()) return null
    const t = peek()
    if (t.type === 'NUM') {
      next()
      return { type: 'num', value: parseFloat(t.value) }
    }
    if (t.type === 'LP') {
      next()
      const e = parseExpr()
      if (e === null) return null
      if (atEnd() || peek().type !== 'RP') return null
      next()
      return e
    }
    if (t.type === 'WORD') {
      next()
      if (!atEnd() && peek().type === 'LP') {
        next()
        const args = parseArgList()
        if (args === null) return null
        if (atEnd() || peek().type !== 'RP') return null
        next()
        return { type: 'call', name: t.value, args }
      }
      if (!atEnd() && peek().type === 'COLON') {
        const save = pos
        next()
        if (!atEnd() && peek().type === 'WORD') {
          const w2 = next()
          return { type: 'range', from: t.value, to: w2.value }
        }
        pos = save
      }
      if (t.value === 'TRUE') return { type: 'bool', value: true }
      if (t.value === 'FALSE') return { type: 'bool', value: false }
      return { type: 'addr', word: t.value }
    }
    return null
  }

  const ast = parseExpr()
  if (ast === null) return null
  if (!atEnd()) return null
  return ast
}
"}

