// Parses the raw sheet text into a Map from canonical address key to
// { content, col, row }. Throws SheetError with a fully-formed message on
// any invalid line.
export function parseSheet(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i]
    const lineNo = i + 1
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    let idx = 0
    while (idx < stripped.length && stripped[idx] !== ' ' && stripped[idx] !== '\t') idx += 1
    const addrRaw = stripped.slice(0, idx)
    let rest = stripped.slice(idx)
    let j = 0
    while (j < rest.length && (rest[j] === ' ' || rest[j] === '\t')) j += 1
    const content = rest.slice(j)

    const addrUpper = addrRaw.toUpperCase()
    const parsed = parseAddress(addrUpper)
    if (!parsed) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${addrUpper}\n`)
    }
    if (cells.has(parsed.key)) {
      throw new SheetError(`error: line ${lineNo}: cell ${parsed.key} is declared twice\n`)
    }
    cells.set(parsed.key, { content, col: parsed.col, row: parsed.row })
  }

  return cells
}

// Returns declared cell keys sorted by ascending column then row.
export function sortedKeys(cells) {
  return [...cells.keys()].sort((ka, kb) => {
    const a = cells.get(ka)
    const b = cells.get(kb)
    if (a.col !== b.col) return a.col - b.col
    return a.row - b.row
  })
}
"}

