      info = ast === null ? { kind: 'literal', value: errVal('#ERR!') } : { kind: 'formula', ast }
    } else {
      info = { kind: 'literal', value: parseLiteral(cell.content) }
    }
    astCache.set(key, info)
    return info
  }

  function evalCell(key) {
    if (valueCache.has(key)) return valueCache.get(key)
    if (state.get(key) === 'computing') return errVal('#CYCLE!')
    state.set(key, 'computing')
    const info = getInfo(key)
    const val = info.kind === 'literal' ? info.value : evalNode(info.ast)
    state.set(key, 'done')
    valueCache.set(key, val)
    return val
  }

  function collectRange(fromWord, toWord) {
    const a = parseAddress(fromWord)
    const b = parseAddress(toWord)
    if (!a || !b) return null
    const minCol = Math.min(a.col, b.col)
    const maxCol = Math.max(a.col, b.col)
    const minRow = Math.min(a.row, b.row)
    const maxRow = Math.max(a.row, b.row)
    const keys = []
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) {
        keys.push(numToLetters(c) + r)
      }
    }
    return keys
  }

  // The list of values contributed by a single argument node (range expands,
  // scalar expr contributes exactly one value).
  function evalArgValues(argNode) {
    if (argNode.type === 'range') {
      const keys = collectRange(argNode.from, argNode.to)
      if (keys === null) return [errVal('#REF!')]
      return keys.map(evalCell)
    }
    return [evalNode(argNode)]
  }

  function evalCall(node) {
    const name = node.name
    if (!KNOWN_FUNCTIONS.has(name)) return errVal('#NAME?')
    const argc = node.args.length

    if (name === 'ABS') {
      if (argc !== 1) return errVal('#ERR!')
      const vals = evalArgValues(node.args[0])
      for (const v of vals) if (v.type === 'error') return v
      if (vals.length !== 1) return errVal('#VALUE!')
      const r = readNumber(vals[0])
      if (!r.ok) return errVal(r.err)
      const res = Math.abs(r.num)
      if (!isFinite(res)) return errVal('#DIV/0!')
      return numVal(res)
    }

    if (name === 'IF') {
      if (argc !== 3) return errVal('#ERR!')
      const condVals = evalArgValues(node.args[0])
      for (const v of condVals) if (v.type === 'error') return v
      if (condVals.length !== 1) return errVal('#VALUE!')
      const cond = condVals[0]
      let condBool
      if (cond.type === 'bool') condBool = cond.value
      else if (cond.type === 'number') condBool = cond.value !== 0
      else return errVal('#VALUE!')
      const branch = condBool ? node.args[1] : node.args[2]
      const vals = evalArgValues(branch)
      for (const v of vals) if (v.type === 'error') return v
      if (vals.length !== 1) return errVal('#VALUE!')
      return vals[0]
    }

    // SUM, MIN, MAX, COUNT, AVG
    if (argc < 1) return errVal('#ERR!')
    const allVals = []
    for (const arg of node.args) allVals.push(...evalArgValues(arg))

    if (name === 'COUNT') {
      for (const v of allVals) if (v.type === 'error') return v
      return numVal(allVals.filter((v) => v.type === 'number').length)
    }

    const nums = []
    for (const v of allVals) {
      const r = readNumber(v)
      if (!r.ok) return errVal(r.err)
      nums.push(r.num)
    }
    let res
    if (name === 'SUM') res = nums.reduce((a, b) => a + b, 0)
    else if (name === 'AVG') res = nums.reduce((a, b) => a + b, 0) / nums.length
    else if (name === 'MIN') res = Math.min(...nums)
    else res = Math.max(...nums)
    if (!isFinite(res)) return errVal('#DIV/0!')
    return numVal(res)
  }

  function evalNode(node) {
    switch (node.type) {
      case 'num':
        return numVal(node.value)
      case 'bool':
        return boolVal(node.value)
      case 'addr': {
        const a = parseAddress(node.word)
        if (!a) return errVal('#REF!')
        return evalCell(a.key)
      }
      case 'range':
        return errVal('#ERR!') // misplaced range, not directly a function argument
      case 'unary': {
        const v = evalNode(node.operand)
        const r = readNumber(v)
        if (!r.ok) return errVal(r.err)
        const res = node.op === '-' ? -r.num : r.num
        if (!isFinite(res)) return errVal('#DIV/0!')
        return numVal(res)
      }
      case 'bin': {
        const l = evalNode(node.left)
        const r = evalNode(node.right)
        if (l.type === 'error') return l
        if (r.type === 'error') return r
        const ln = readNumber(l)
        if (!ln.ok) return errVal(ln.err)
        const rn = readNumber(r)
        if (!rn.ok) return errVal(rn.err)
        let res
        switch (node.op) {
          case '+': res = ln.num + rn.num; break
          case '-': res = ln.num - rn.num; break
          case '*': res = ln.num * rn.num; break
          case '/':
            if (rn.num === 0) return errVal('#DIV/0!')
            res = ln.num / rn.num
            break
          case '^': res = Math.pow(ln.num, rn.num); break
        }
        if (!isFinite(res)) return errVal('#DIV/0!')
        return numVal(res)
      }
      case 'cmp': {
        const l = evalNode(node.left)
        const r = evalNode(node.right)
        if (l.type === 'error') return l
        if (r.type === 'error') return r
        const c = compareValues(l, r)
        let res
        switch (node.op) {
          case '=': res = c === 0; break
          case '<>': res = c !== 0; break
          case '<': res = c < 0; break
          case '<=': res = c <= 0; break
          case '>': res = c > 0; break
          case '>=': res = c >= 0; break
        }
        return boolVal(res)
      }
      case 'call':
        return evalCall(node)
      default:
        return errVal('#ERR!')
    }
  }

  return { evalCell, getInfo }
}

// Walk a formula AST collecting every distinct addressable cell it names
// directly, ranges expanded. Returns a Set of keys.
export function collectDeps(ast) {
  const found = new Set()

  function visitAddr(word) {
    const a = parseAddress(word)
    if (a) found.add(a.key)
  }

  function visitRange(fromWord, toWord) {
    const a = parseAddress(fromWord)
    const b = parseAddress(toWord)
    if (!a || !b) return
    const minCol = Math.min(a.col, b.col)
    const maxCol = Math.max(a.col, b.col)
    const minRow = Math.min(a.row, b.row)
    const maxRow = Math.max(a.row, b.row)
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) {
        found.add(numToLetters(c) + r)
      }
    }
  }

  function visit(node) {
    switch (node.type) {
      case 'num':
      case 'bool':
        return
      case 'addr':
        visitAddr(node.word)
        return
      case 'range':
        visitRange(node.from, node.to)
        return
      case 'unary':
        visit(node.operand)
        return
      case 'bin':
      case 'cmp':
        visit(node.left)
        visit(node.right)
        return
      case 'call':
        for (const arg of node.args) visit(arg)
        return
    }
  }

  visit(ast)
  return found
}
"}

